gcflcm: [
 {id:'gl1',t:1,skill:'gcf',q:'Find the GCF of $12$ and $18$.',a:'6',
  hint:'The largest number dividing both.',s:['Factors of $12$: $1,2,3,4,6,12$','Factors of $18$: $1,2,3,6,9,18$','Largest shared: $6$']},
 {id:'gl2',t:1,skill:'lcm',q:'Find the LCM of $4$ and $6$.',a:'12',
  hint:'The smallest number both divide into.',s:['Multiples of $6$: $6, 12, \\ldots$','$12$ is the first also divisible by $4$.']},
 {id:'gl3',t:1,skill:'primefact',q:'What is the prime factorisation of $36$?',c:['$2^2 \\cdot 3^2$','$2^3 \\cdot 3$','$4 \\cdot 9$','$6^2$'],a:0,
  hint:'Break it down until everything is prime.',s:['$36 = 4 \\times 9 = 2^2 \\cdot 3^2$','$4$, $9$ and $6$ are not prime, so those answers are incomplete.']},
 {id:'gl4',t:1,skill:'gcf',q:'Find the GCF of $8$ and $15$.',a:'1',
  hint:'Do they share any factor bigger than $1$?',s:['$8 = 2^3$ and $15 = 3 \\cdot 5$','No shared primes, so the GCF is $1$ — they are relatively prime.']},
 {id:'gl5',t:1,skill:'lcm',q:'Find the LCM of $5$ and $7$.',a:'35',
  hint:'They share no factors, so just multiply.',s:['$5$ and $7$ are relatively prime','LCM $= 5 \\times 7 = 35$']},
 {id:'gl6',t:2,skill:'gcf',q:'Find the GCF of $24$ and $36$.',a:'12',
  hint:'Factorise both, then take shared primes at their lowest powers.',
  s:['$24 = 2^3 \\cdot 3$, $36 = 2^2 \\cdot 3^2$','Shared at lowest powers: $2^2 \\cdot 3$','$= 12$']},
 {id:'gl7',t:2,skill:'lcm',q:'Find the LCM of $12$ and $18$.',a:'36',
  hint:'Every prime at its highest power.',s:['$12 = 2^2 \\cdot 3$, $18 = 2 \\cdot 3^2$','Highest powers: $2^2 \\cdot 3^2 = 36$']},
 {id:'gl8',t:2,skill:'gcf',q:'Find the GCF of $18$ and $30$.',a:'6',
  hint:'Factorise both first.',s:['$18 = 2 \\cdot 3^2$, $30 = 2 \\cdot 3 \\cdot 5$','Shared: $2 \\cdot 3 = 6$']},
 {id:'gl9',t:2,skill:'lcm',q:'Find the LCM of $8$ and $12$.',a:'24',
  hint:'$8 = 2^3$ and $12 = 2^2 \\cdot 3$.',s:['Highest powers: $2^3 \\cdot 3$','$= 24$']},
 {id:'gl10',t:2,skill:'word',q:'Two lighthouses flash every $12$ and $18$ seconds, together right now. After how many seconds do they next flash together?',a:'36',unit:'sec',
  hint:'The next shared moment is later, so you want the LCM.',s:['LCM of $12$ and $18$','$2^2 \\cdot 3^2 = 36$ seconds']},
 {id:'gl11',t:2,skill:'word',q:'A florist has $48$ roses and $36$ tulips and wants identical bunches using every flower. What is the greatest number of bunches?',a:'12',unit:'bunches',
  hint:'The answer must divide both numbers, so it is smaller — GCF.',
  s:['$48 = 2^4 \\cdot 3$, $36 = 2^2 \\cdot 3^2$','GCF $= 2^2 \\cdot 3 = 12$','Each bunch: $4$ roses and $3$ tulips.']},
 {id:'gl12',t:2,skill:'product',q:'Two numbers have GCF $6$ and LCM $90$. One of them is $18$. Find the other.',a:'30',
  hint:'GCF $\\times$ LCM $=$ the product of the two numbers.',
  s:['$6 \\times 90 = 540$','$540 \\div 18 = 30$','Check: GCF$(18, 30) = 6$ &check;']},
 {id:'gl13',t:3,skill:'gcf',q:'Find the GCF of $84$ and $126$.',a:'42',
  hint:'$84 = 2^2 \\cdot 3 \\cdot 7$.',
  s:['$84 = 2^2 \\cdot 3 \\cdot 7$','$126 = 2 \\cdot 3^2 \\cdot 7$','Shared at lowest powers: $2 \\cdot 3 \\cdot 7 = 42$']},
 {id:'gl14',t:3,skill:'lcm',q:'Find the LCM of $15$, $20$ and $25$.',a:'300',
  hint:'Factorise all three, then take every prime at its highest power.',
  s:['$15 = 3 \\cdot 5$, $20 = 2^2 \\cdot 5$, $25 = 5^2$','Highest powers: $2^2 \\cdot 3 \\cdot 5^2$','$= 4 \\times 3 \\times 25 = 300$']},
 {id:'gl15',t:3,skill:'product',q:'Two numbers have GCF $8$ and LCM $48$. One is $16$. Find the other.',a:'24',
  hint:'Use GCF $\\times$ LCM $= a \\times b$.',s:['$8 \\times 48 = 384$','$384 \\div 16 = 24$']},
 {id:'gl16',t:3,skill:'word',q:'What is the smallest number divisible by $6$, $8$ and $15$?',a:'120',
  hint:'"Smallest number divisible by all" is the LCM.',
  s:['$6 = 2 \\cdot 3$, $8 = 2^3$, $15 = 3 \\cdot 5$','Highest powers: $2^3 \\cdot 3 \\cdot 5$','$= 120$']},
],
